#include <iostream>

// Precondicion de esta practica: marca empieza en 0;
// se hacen exactamente dos llamadas con digitos entre 1 y 9.
int registrar(int& marca, int digito) {
    marca = marca * 10 + digito;
    return digito;
}

int sumar(int primero, int segundo) {
    return primero + segundo;
}

int main() {
    int marca{0};
    int primero = registrar(marca, 2);
    int segundo = registrar(marca, 7);
    int resultado = sumar(primero, segundo);
    std::cout << resultado << ':' << marca;
    return 0;
}
